import math
from fractions import Fraction

def is_perfect_square_rational(num):
    """Checks if a rational number is the square of a rational number."""
    if num.denominator == 0:
        return False

    # Simplify the fraction
    f = Fraction(num.numerator, num.denominator)

    # If numerator and denominator are both perfect squares, the fraction is a perfect square.
    def is_square_integer(n):
        if n < 0:
            return False
        if n == 0:
            return True
        # Check if sqrt(n) is an integer
        sqrt_n = math.isqrt(n)
        return sqrt_n * sqrt_n == n

    return is_square_integer(f.numerator) and is_square_integer(f.denominator)

def check_b_squared_is_rational_square(a):
    if a == 2:
        return None

    numerator = a**3 - 2*a**2 - a
    denominator = a - 2

    b_squared = Fraction(numerator, denominator)

    if is_perfect_square_rational(b_squared):
        return True
    return False

# Check a range of integers, e.g., from -10 to 10, excluding 2.
results = {}
for a in range(-10, 11):
    if a != 2:
        is_sq = check_b_squared_is_rational_square(a)
        if is_sq:
            results[a] = "YES"
        else:
            results[a] = "NO"

print("Results for integers a in [-10, 10] (a!=2):")
for a, result in sorted(results.items()):
    print(f"a={a}: {result}")

# Specific check for a=0
a0_check = check_b_squared_is_rational_square(0)
print(f"\nSpecific check for a=0: {a0_check}")

